<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
$user=require_login();
$publicId=(string)($_GET['deal']??'');
$stmt=db()->prepare("SELECT public_id,title,terms,currency,amount_minor,fee_minor,status FROM deals WHERE public_id=? AND buyer_id=? LIMIT 1");
$stmt->execute([$publicId,$user['id']]); $deal=$stmt->fetch();
if (!$deal) { http_response_code(404); exit('Deal not found.'); }
if ($deal['status']!=='awaiting_payment') { http_response_code(409); exit('This deal is not ready for payment. Both parties must agree to the terms first.'); }
if ($deal['currency'] === 'USDT') {
    $setupIssue=true;
} elseif (empty($config['hashpay_account_id']) || str_contains($config['hashpay_account_id'],'REPLACE') || ((int)$deal['amount_minor']%100)!==0) {
    $setupIssue=true;
} else $setupIssue=false;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pay for deal · XWADDA.KE</title><link rel="stylesheet" href="assets/styles.css"><style>.pay-card{max-width:560px;margin:8vh auto;padding:26px;background:#fff;border:1px solid #e8ece7;border-radius:12px}.pay-card h1{font:700 23px var(--display)}.pay-amount{font:700 25px var(--display);margin:12px 0}.pay-note{font-size:11px;line-height:1.6;color:#78847c;background:#f5f7f4;padding:12px;border-radius:6px;margin:17px 0}.pay-state{font-size:11px;margin:12px 0;min-height:17px;color:#32674a}.pay-state.error{color:#a95042}.pay-terms{white-space:pre-wrap;background:#f7f9f6;padding:12px;border-radius:6px;font-size:10px;max-height:180px;overflow:auto}.crypto-choice{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.crypto-choice button{border:1px solid #bbb;background:#fff;padding:10px;border-radius:7px;font-weight:700}.crypto-choice button:hover{background:#eee}.crypto-box{margin-top:16px;padding:16px;border:1px solid #ccc;border-radius:9px;text-align:center}.crypto-box img{width:min(240px,100%);height:auto;display:block;margin:12px auto}.crypto-address{word-break:break-all;font:12px monospace;background:#f4f4f4;padding:10px;border-radius:6px}.copy-btn{margin:8px;border:1px solid #aaa;background:#fff;padding:8px 12px;border-radius:5px}.crypto-warn{font-size:11px;line-height:1.55;background:#f2f2f2;padding:12px;border-radius:6px}.fee-breakdown{border:1px solid #ddd;border-radius:8px;padding:11px 13px;font-size:12px}.fee-breakdown>div{display:flex;justify-content:space-between;padding:5px 0}.fee-breakdown span{color:#666}.fee-breakdown .fee-total{border-top:1px solid #ccc;margin-top:5px;padding-top:10px;font-weight:800}.fee-breakdown .fee-total b{font-size:14px}</style></head><body><main class="pay-card"><div class="eyebrow">XWADDA.KE · PAYMENT</div><h1><?=e($deal['title'])?></h1><div class="pay-amount"><?=e($deal['currency'])?> <?=number_format(((int)$deal['amount_minor'])/100,2)?></div><div class="fee-breakdown"><div><span>Agreed deal amount</span><b><?=e($deal['currency'])?> <?=number_format(((int)$deal['amount_minor'])/100,2)?></b></div><div><span>Buyer-paid escrow fee</span><b><?=e($deal['currency'])?> <?=number_format(((int)$deal['fee_minor'])/100,2)?></b></div><div class="fee-total"><span>Total due</span><b><?=e($deal['currency'])?> <?=number_format(((int)$deal['amount_minor']+(int)$deal['fee_minor'])/100,2)?></b></div></div><div class="pay-note">The seller accepted these terms. Use only the payment option and network shown below. Never send USDT on a different network.</div><details><summary>Review agreed terms</summary><div class="pay-terms"><?=e($deal['terms'])?></div></details><?php if($deal['currency']==='USDT'):?><p class="crypto-warn"><b>Manual confirmation:</b> Send the exact amount in USDT on the selected network. XWADDA will not mark this deal funded until an administrator checks the on-chain transfer. Wrong-network and short payments may not be recoverable.</p><div class="crypto-choice"><button type="button" data-network="tron">USDT · TRC20</button><button type="button" data-network="bsc">USDT · BEP20</button></div><div id="cryptoBox" class="crypto-box" hidden></div><script>
const networks={tron:{label:'TRON · TRC20',address:'TMVimVUeR8u9R6HdjfGzeUeeZtzi19KM72',qr:'assets/usdt-trc20-qr.png'},bsc:{label:'BNB Smart Chain · BEP20',address:'0x352b897c40ae74619ed792932a1e561ebcb7331e',qr:'assets/usdt-bep20-qr.png'}};
document.querySelectorAll('[data-network]').forEach(button=>button.addEventListener('click',async()=>{const network=button.dataset.network;button.disabled=true;try{const response=await fetch('create-crypto-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?=json_encode(csrf_token())?>},body:JSON.stringify({deal:<?=json_encode($deal['public_id'])?>,network})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not prepare payment.');const n=networks[network],box=document.getElementById('cryptoBox');box.hidden=false;box.innerHTML='<b>'+n.label+'</b><img src="'+n.qr+'" alt="USDT '+n.label+' QR code"><div><b>Send exactly <?=number_format(((int)$deal['amount_minor']+(int)$deal['fee_minor'])/100,2)?> USDT</b></div><div class="crypto-address">'+n.address+'</div><button class="copy-btn" type="button">Copy address</button><p>Payment reference: <b>'+data.reference+'</b></p><p class="crypto-warn">Keep this page open. Your payment remains pending until an XWADDA administrator verifies the transaction and confirms it in the admin console.</p><form id="txHashForm"><label>Transaction hash after sending<input name="tx_hash" required minlength="64" maxlength="64" pattern="[A-Fa-f0-9]{64}" placeholder="64-character transaction hash"></label><button class="copy-btn" type="submit">Submit hash for admin review</button><small id="hashSubmitState"></small></form>';box.querySelector('.copy-btn').onclick=()=>navigator.clipboard.writeText(n.address);box.querySelector('#txHashForm').addEventListener('submit',async event=>{event.preventDefault();const f=event.currentTarget,state=box.querySelector('#hashSubmitState');const r=await fetch('submit-crypto-hash.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':<?=json_encode(csrf_token())?>},body:JSON.stringify({intent:data.intent,tx_hash:f.tx_hash.value})});const result=await r.json();if(!r.ok){state.textContent=result.error||'Submission failed.';return}state.textContent='Hash submitted. The deal remains pending until an administrator verifies it.'})}catch(error){alert(error.message)}finally{button.disabled=false}}));
</script><?php elseif($setupIssue):?><p class="pay-state error">HashBack M-Pesa details are not configured, or this amount is not a whole KES amount. Contact the site administrator.</p><?php else:?><button class="button button-primary" id="payButton">Pay with M-PESA →</button><p class="pay-state" id="payState" role="status"></p><script src="https://pay.hashback.co.ke/hashpay.js"></script><script>
const csrf=<?=json_encode(csrf_token())?>, dealId=<?=json_encode($deal['public_id'])?>;
const button=document.getElementById('payButton'), state=document.getElementById('payState');
button.addEventListener('click',async()=>{
  button.disabled=true;state.textContent='Preparing secure payment…';state.classList.remove('error');
  try{
    const response=await fetch('create-mpesa-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({deal:dealId})});
    const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not prepare payment.');
    const handler=HashPay.setup({account:data.account,amount:data.amount,reference:data.reference,onSuccess:()=>watchPayment(data.intent),onCancel:()=>{state.textContent='Payment window closed. It may still be processing; do not pay again until the status is confirmed.'},onError:()=>{state.textContent='Payment status is uncertain. Contact support before trying again.';state.classList.add('error')}});
    state.textContent='Approve the M-PESA prompt on your phone.';handler.openIframe();
  }catch(error){state.textContent=error.message;state.classList.add('error');button.disabled=false}
});
async function watchPayment(id){state.textContent='Payment submitted. Verifying the server confirmation…';for(let i=0;i<20;i++){await new Promise(r=>setTimeout(r,2500));const r=await fetch('payment-status.php?id='+encodeURIComponent(id));const s=await r.json();if(s.status==='confirmed'){state.textContent='Payment confirmed. Your deal is funded.';button.textContent='Payment confirmed';return}if(s.status==='failed'||s.status==='exception'){state.textContent='Payment needs attention. Contact support before paying again.';state.classList.add('error');return}}state.textContent='Still waiting for confirmation. Do not pay again; contact support to reconcile the pending attempt.'}
</script><?php endif;?><p style="margin-top:18px"><a class="link-button" href="index.php">← Return to workspace</a></p></main><footer class="site-copyright">© <?=gmdate('Y')?> XWADDA.KE. All rights reserved.</footer></body></html>
